insert into admin_audit_log (source, action, table_name, row_id, summary, changes)
select 'sql', 'article.rewrite.manual', 'blog_posts', id::text, 'the-island-of-makers-cyprus-crafts rewritten', jsonb_build_object('before', jsonb_build_object('content_en', content_en, 'title_en', title_en, 'content_el', content_el, 'title_el', title_el, 'content_ro', content_ro, 'title_ro', title_ro, 'content_ar', content_ar, 'title_ar', title_ar, 'content_de', content_de, 'title_de', title_de, 'content_pl', content_pl, 'title_pl', title_pl, 'content_ru', content_ru, 'title_ru', title_ru))
